        self.expect(Token::Keyword(Keyword::From))?;

        let table = self.next_ident()?;

        let where_clause = if self.next_is(Token::Keyword(Keyword::Where)) {
            Some(self.parse_expression()?)
        } else {
            None
        };

        Ok(ast::Statement::Delete { table, r#where: where_clause })
    }

