                Token::Minus => ast::Expression::Operator(ast::Operator::Subtract(Box::new(lhs), Box::new(rhs))),
                Token::Asterisk => ast::Expression::Operator(ast::Operator::Multiply(Box::new(lhs), Box::new(rhs))),
                Token::Slash => ast::Expression::Operator(ast::Operator::Divide(Box::new(lhs), Box::new(rhs))),
                Token::Percent => ast::Expression::Operator(ast::Operator::Remainder(Box::new(lhs), Box::new(rhs))),
                Token::Caret => ast::Expression::Operator(ast::Operator::Exponentiate(Box::new(lhs), Box::new(rhs))),
                _ => break,
            };
        }

        Ok(lhs)
    }

    /// Parses a primary expression (literals, columns, functions, etc.).
    fn parse_primary(&mut self) -> Result<ast::Expression> {
        let token = self.next()?;

        match token {
            Token::Asterisk => Ok(ast::Expression::All),
            Token::Ident(name) => {
